package app.sff.signal;
import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.net.Uri;
import android.graphics.Color;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import java.util.*;
public class Main extends Activity {
 static final String DEFAULT_ORIGIN="__SFF_SERVER_URL__";
 WebView web; LinearLayout shell; String origin; PermissionRequest pending; ValueCallback<Uri[]> files;
 long lastNotice;
 public class Notices {
 @JavascriptInterface public void ask(){runOnUiThread(()->{if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},35);});}
 @JavascriptInterface public void show(String title){runOnUiThread(()->{if(System.currentTimeMillis()-lastNotice<2000||!same(Uri.parse(web.getUrl()==null?"":web.getUrl())))return;lastNotice=System.currentTimeMillis();NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(!manager.areNotificationsEnabled())return;manager.createNotificationChannel(new NotificationChannel("messages","Poruke",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(Main.this,0,new Intent(Main.this,Main.class).setFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);manager.notify(4178,new Notification.Builder(Main.this,"messages").setSmallIcon(getResources().getIdentifier("mark","drawable",getPackageName())).setContentTitle("SFF").setContentText(title.substring(0,Math.min(100,title.length()))).setContentIntent(open).setAutoCancel(true).build());});}
 }
 boolean same(Uri uri){return origin!=null&&origin.equals(uri.getScheme()+"://"+uri.getEncodedAuthority());}
 void config(){EditText input=new EditText(this);input.setSingleLine();input.setInputType(17);input.setHint("https://sff.example.com");input.setText(origin==null?"":origin);
 AlertDialog d=new AlertDialog.Builder(this).setTitle("SFF · Adresa servera").setMessage("Unesi HTTPS adresu SFF servera. Za USB vezu koristi http://localhost:4178 uz adb reverse.").setView(input).setPositiveButton("Poveži se",null).setNegativeButton("Zatvori",null).create();d.show();d.getButton(-1).setOnClickListener(v->{Uri u=Uri.parse(input.getText().toString().trim());if(u.getHost()==null||u.getUserInfo()!=null||!("https".equals(u.getScheme())||("http".equals(u.getScheme())&&Arrays.asList("localhost","127.0.0.1").contains(u.getHost())))){input.setError("Potrebna je ispravna adresa servera.");return;}origin=u.getScheme()+"://"+u.getEncodedAuthority();getPreferences(0).edit().putString("server",origin).apply();web.clearHistory();web.loadUrl(origin+"/");d.dismiss();});}
 @Override public void onCreate(Bundle b){super.onCreate(b);shell=new LinearLayout(this);shell.setOrientation(1);shell.setBackgroundColor(Color.rgb(21,19,24));setContentView(shell);
 shell.setOnApplyWindowInsetsListener((view,i)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets s=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.ime()|WindowInsets.Type.displayCutout());view.setPadding(s.left,s.top,s.right,s.bottom);}else view.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});
 TextView bar=new TextView(this);bar.setText("   SFF");bar.setTextColor(0xffffa3ad);bar.setPadding(12,12,12,12);shell.addView(bar);web=new WebView(this);web.setBackgroundColor(0xff151318);shell.addView(web,new LinearLayout.LayoutParams(-1,0,1));web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMediaPlaybackRequiresUserGesture(false);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri uri=r.getUrl();if(same(uri))return false;if(r.hasGesture()&&Arrays.asList("https","http").contains(uri.getScheme()))new AlertDialog.Builder(Main.this).setTitle("Spoljni link").setMessage(uri.getHost()).setNegativeButton("Zatvori",null).setPositiveButton("Kopiraj link",(dialog,which)->{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("SFF",uri.toString()));}).show();return true;}});
 web.addJavascriptInterface(new Notices(),"SFFAndroid");web.setWebChromeClient(new WebChromeClient(){public void onPermissionRequest(PermissionRequest p){if(!same(p.getOrigin())){p.deny();return;}pending=p;ArrayList<String> ask=new ArrayList<>();for(String r:p.getResources()){String permission=r.equals(PermissionRequest.RESOURCE_AUDIO_CAPTURE)?android.Manifest.permission.RECORD_AUDIO:r.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE)?android.Manifest.permission.CAMERA:null;if(permission!=null&&checkSelfPermission(permission)!=PackageManager.PERMISSION_GRANTED)ask.add(permission);}if(ask.isEmpty())grant();else requestPermissions(ask.toArray(new String[0]),25);}
 public void onPermissionRequestCanceled(PermissionRequest p){if(pending==p)pending=null;}
 public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> cb,FileChooserParams p){if(files!=null)files.onReceiveValue(null);files=cb;try{startActivityForResult(p.createIntent(),42);return true;}catch(Exception e){files=null;return false;}}});
 web.setDownloadListener((url,ua,disposition,mime,size)->{Uri uri=Uri.parse(url);if(!same(uri))return;DownloadManager.Request r=new DownloadManager.Request(uri);String cookie=CookieManager.getInstance().getCookie(url);if(cookie!=null)r.addRequestHeader("Cookie",cookie);String name=URLUtil.guessFileName(url,disposition,mime).replaceAll("[^a-zA-Z0-9._-]","_");r.setDestinationInExternalFilesDir(this,Environment.DIRECTORY_DOWNLOADS,name);r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(r);});
 if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->{if(web.canGoBack())web.goBack();else finish();});
 origin=DEFAULT_ORIGIN.startsWith("https://")?DEFAULT_ORIGIN:getPreferences(0).getString("server",null);if(origin==null && getIntent().getBooleanExtra("usb",false)){origin="http://localhost:4178";getPreferences(0).edit().putString("server",origin).apply();}if(origin==null)config();else web.loadUrl(origin+"/");}
 void grant(){if(pending==null)return;ArrayList<String> ok=new ArrayList<>();for(String r:pending.getResources())if((r.equals(PermissionRequest.RESOURCE_AUDIO_CAPTURE)&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==0)||(r.equals(PermissionRequest.RESOURCE_VIDEO_CAPTURE)&&checkSelfPermission(android.Manifest.permission.CAMERA)==0))ok.add(r);if(ok.size()>0&&same(pending.getOrigin()))pending.grant(ok.toArray(new String[0]));else pending.deny();pending=null;}
 @Override public void onRequestPermissionsResult(int c,String[] p,int[] r){super.onRequestPermissionsResult(c,p,r);if(c==25)grant();}
 @Override protected void onActivityResult(int c,int r,Intent d){super.onActivityResult(c,r,d);if(c==42&&files!=null){files.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(r,d));files=null;}}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}
